import sys

def multiply(one, two, m, mod):
    res = [[0] * m for _ in range(m)]
    for i in range(m):
        for j in range(m):
            for k in range(m):
                res[i][j] = (res[i][j] + one[i][k] * two[k][j]) % mod
    return res

def power(exp, base, m, mod):
    if exp == 1:
        return base
    res = power(exp // 2, base, m, mod)
    res = multiply(res, res, m, mod)
    if exp % 2 == 1:
        res = multiply(res, base, m, mod)
    return res

